 public static void main(String[] args)throws Exception{var snapshot=snapshot();var doc=new AbilityVisualEditorDocument(snapshot);header(doc);gameplay(doc);tree(doc);selection(snapshot);localization();baselineSelection(snapshot);bezierReduction();liveMutation();duplicateSafety(snapshot);schema(doc);burstCount();lifecycle();staleConflictPreservesSelectedDraft();sessionApplyDenied();strictResponseLifecycle();timeline(snapshot.visual());layout();japaneseInspectorLayout();headerReachability();controlPointPaging();hudLayout();worldPreviewLifecycle(snapshot);widgetContract();guards();}
 private static void header(AbilityVisualEditorDocument d){assert !SkillEditorUiController.header(d,false,true,true,true).apply();d.execute(AbilityVisualCommands.setScalar("circle","radius",new SkillVfxModel.Literal(4)));var h=SkillEditorUiController.header(d,false,true,true,true);assert h.apply()&&h.undo()&&h.dirty()&&!SkillEditorUiController.header(d,true,true,true,true).apply();assert h.dirtyLabel().equals("● 未反映の変更があります")&&SkillEditorUiController.header(null,false,true,true,true).dirtyLabel().equals("変更なし");assert SkillEditorUiController.feedback(SkillEditorController.Feedback.STALE,"").contains("下書きは保持");assert SkillEditorUiController.feedback(SkillEditorController.Feedback.APPLIED,"").contains("サーバー再起動");d.undo();}
 private static void gameplay(AbilityVisualEditorDocument d){var p=new SkillGameplayPanel();var a=p.actions(d);assert a.size()==3&&a.get(0).type().equals("Wait")&&a.get(1).type().equals("CircleTelegraph")&&a.get(2).type().equals("Damage");assert a.get(0).fields().containsKey("ticks")&&a.get(1).fields().containsKey("radius")&&a.get(2).fields().containsKey("elements");p.select(99,d);assert p.selected()==2;}
 private static void tree(AbilityVisualEditorDocument d){var tree=new SkillVisualTreePanel();assert tree.hooks().contains(SkillVfxModel.Hook.CANCEL)&&!tree.editable(SkillVfxModel.Hook.TRAVEL);var hook=SkillVfxModel.Hook.CAST;d.execute(AbilityVisualCommands.addEmission(hook,new SkillVfxModel.Emission("two",-1,List.of(SkillVfxModel.defaults("point-two",SkillVfxModel.PrimitiveType.POINT)))));d.execute(AbilityVisualCommands.setEmissionActionIndex(hook,"two",1));assert d.visual().emissions(hook).stream().filter(e->e.id().equals("two")).findFirst().orElseThrow().actionIndex()==1;d.execute(AbilityVisualCommands.add(hook,"two",SkillVfxModel.defaults("line-two",SkillVfxModel.PrimitiveType.LINE)));d.execute(AbilityVisualCommands.duplicate(hook,"two","line-two"));d.execute(AbilityVisualCommands.movePrimitive(hook,"two","line-two",0));d.execute(AbilityVisualCommands.duplicateEmission(hook,"two"));d.execute(AbilityVisualCommands.moveEmission(hook,"two",0));d.execute(AbilityVisualCommands.remove("point-two"));d.execute(AbilityVisualCommands.removeEmission(hook,"two"));assert d.dirty()&&d.undo()&&d.redo();while(d.history().canUndo())d.undo();assert !d.dirty();}
 private static void selection(SkillVfxModel.Snapshot snapshot){var d=new AbilityVisualEditorDocument(snapshot);var first=SkillVfxSelection.resolve(d,null);assert first.hook()==SkillVfxModel.Hook.CAST&&first.emissionId().equals("cast")&&first.primitiveId().equals("cast-point");assert SkillVfxSelection.resolve(d,first).equals(first);var hookOnly=new SkillVfxSelection.Value(SkillVfxModel.Hook.TELEGRAPH,null,null);assert SkillVfxSelection.resolve(d,hookOnly).equals(hookOnly);var emissionOnly=new SkillVfxSelection.Value(SkillVfxModel.Hook.CAST,"cast",null);assert SkillVfxSelection.resolve(d,emissionOnly).equals(emissionOnly);var replacement=new AbilityVisualEditorDocument(snapshot);assert SkillVfxSelection.resolve(replacement,null).equals(first);var empty=new AbilityVisualEditorDocument(new SkillVfxModel.Snapshot(UUID.randomUUID(),1,"projects:empty","Empty","projects:vfx/empty","b","e",false,List.of(),new SkillVfxModel.Visual("projects:vfx/empty",List.of())));assert !SkillVfxSelection.resolve(empty,null).selected();}
 private static void localization(){for(var hook:SkillVfxModel.Hook.values())assert !SkillVfxDisplay.hook(hook).isBlank();for(var type:SkillVfxModel.PrimitiveType.values())assert !SkillVfxDisplay.primitive(type).isBlank();for(var field:List.of("delayTicks","durationTicks","argb","opacity","width","density","seed","offsetX","offsetY","offsetZ","yaw","size","length","controlPoints","radius","startAngle","sweepAngle","angle","height","turns","count")){assert !SkillVfxDisplay.field(field).name().equals(field)&&!SkillVfxDisplay.field(field).description().isBlank();}assert SkillEditorUiController.number("bad").error().equals("有効な数値を入力してください。")&&SkillEditorUiController.integer("300",1,64).error().equals("1〜64 の整数を入力してください。")&&SkillEditorUiController.longValue("bad").error().equals("整数を入力してください。")&&SkillEditorUiController.argb("#123").error().equals("#AARRGGBB または #RRGGBB で入力してください。");assert AbilityVisualPropertySchemas.description("argb").contains("#")&&AbilityVisualPropertySchemas.description("controlPoints").contains("座標")&&AbilityVisualPropertySchemas.description("radius").contains("半径");}
 private static void baselineSelection(SkillVfxModel.Snapshot snapshot){var d=new AbilityVisualEditorDocument(snapshot);var retained=SkillVfxSelection.resolve(d,null);d.select("primitive",retained.primitiveId());d.replaceBaseline(snapshot);assert d.selection().primaryId()==null;retained=SkillVfxSelection.resolve(d,retained);d.select("primitive",retained.primitiveId());var width=AbilityVisualPropertySchemas.schema(SkillVfxModel.PrimitiveType.POINT).property("width");@SuppressWarnings({"rawtypes","unchecked"}) io.github.gyai.projects.editor.core.PropertyDescriptor raw=width;raw.write(d,.75d);assert d.selectedValue("width").equals(.75d);var empty=new AbilityVisualEditorDocument(new SkillVfxModel.Snapshot(UUID.randomUUID(),1,"projects:none","None","projects:vfx/none","b","e",false,List.of(),new SkillVfxModel.Visual("projects:vfx/none",List.of())));assert !SkillVfxSelection.resolve(empty,retained).selected();}
 private static void bezierReduction(){var p=SkillVfxModel.defaults("bezier",SkillVfxModel.PrimitiveType.BEZIER);var visual=new SkillVfxModel.Visual("projects:vfx/bezier",List.of(new SkillVfxModel.HookBinding(SkillVfxModel.Hook.CAST,List.of(new SkillVfxModel.Emission("cast",-1,List.of(p))))));var d=new AbilityVisualEditorDocument(new SkillVfxModel.Snapshot(UUID.randomUUID(),1,"projects:bezier","Bezier",visual.id(),"b","e",false,List.of(),visual));d.select("primitive","bezier");var four=List.of(new SkillVfxModel.Vec(1,0,0),new SkillVfxModel.Vec(2,0,0),new SkillVfxModel.Vec(3,0,0),new SkillVfxModel.Vec(4,0,0));@SuppressWarnings({"rawtypes","unchecked"}) io.github.gyai.projects.editor.core.PropertyDescriptor raw=AbilityVisualPropertySchemas.schema(SkillVfxModel.PrimitiveType.BEZIER).property("controlPoints");raw.write(d,four);raw.write(d,List.of(four.get(0),four.get(1),four.get(3)));assert ((List<SkillVfxModel.Vec>)d.selectedValue("controlPoints")).getLast().x()==4&&d.undo()&&((List<?>)d.selectedValue("controlPoints")).size()==4&&d.redo()&&((List<SkillVfxModel.Vec>)d.selectedValue("controlPoints")).getLast().x()==4;}
 private static void liveMutation(){var line=SkillVfxModel.defaults("line",SkillVfxModel.PrimitiveType.LINE);var point=SkillVfxModel.defaults("point",SkillVfxModel.PrimitiveType.POINT);var arc=SkillVfxModel.defaults("arc",SkillVfxModel.PrimitiveType.ARC);var visual=new SkillVfxModel.Visual("projects:vfx/live",List.of(new SkillVfxModel.HookBinding(SkillVfxModel.Hook.CAST,List.of(new SkillVfxModel.Emission("cast",-1,List.of(line,point,arc))))));var d=new AbilityVisualEditorDocument(new SkillVfxModel.Snapshot(UUID.randomUUID(),1,"projects:live","Live",visual.id(),"b","e",false,List.of(),visual));assert SkillVfxMutation.writeControls(d,"line",p->{var c=new ArrayList<>(p.controls());var v=c.getFirst();c.set(0,new SkillVfxModel.Vec(3,v.y(),v.z()));return c;});assert SkillVfxMutation.writeControls(d,"line",p->{var c=new ArrayList<>(p.controls());var v=c.getFirst();c.set(0,new SkillVfxModel.Vec(v.x(),4,v.z()));return c;});var liveLine=SkillVfxMutation.current(d,"line").orElseThrow();assert liveLine.controls().getFirst().x()==3&&liveLine.controls().getFirst().y()==4;d.select("primitive","point");@SuppressWarnings({"rawtypes","unchecked"}) io.github.gyai.projects.editor.core.PropertyDescriptor width=AbilityVisualPropertySchemas.schema(SkillVfxModel.PrimitiveType.POINT).property("width");width.write(d,.75d);int originalArgb=point.argb();assert SkillVfxMutation.replace(d,"point",p->new SkillVfxModel.Primitive(p.id(),p.type(),p.delayTicks(),p.durationTicks(),0xFF112233,p.width(),p.density(),p.seed(),p.offset(),p.yaw(),p.values(),p.controls()));var livePoint=SkillVfxMutation.current(d,"point").orElseThrow();assert livePoint.width()==.75&&livePoint.argb()==0xFF112233;Object originalRadius=arc.value("radius");Object originalStart=arc.value("startAngle");assert SkillVfxMutation.replace(d,"arc",p->p.withValue("radius",new SkillVfxModel.Literal(2)));assert SkillVfxMutation.replace(d,"arc",p->p.withValue("startAngle",new SkillVfxModel.Literal(3)));var liveArc=SkillVfxMutation.current(d,"arc").orElseThrow();assert ((SkillVfxModel.Literal)liveArc.value("radius")).value()==2&&((SkillVfxModel.Literal)liveArc.value("startAngle")).value()==3;assert d.undo()&&Objects.equals(SkillVfxMutation.current(d,"arc").orElseThrow().value("startAngle"),originalStart);assert d.undo()&&Objects.equals(SkillVfxMutation.current(d,"arc").orElseThrow().value("radius"),originalRadius);assert d.undo()&&SkillVfxMutation.current(d,"point").orElseThrow().argb()==originalArgb&&SkillVfxMutation.current(d,"point").orElseThrow().width()==.75;assert d.undo()&&SkillVfxMutation.current(d,"point").orElseThrow().width()==point.width();}
 private static void schema(AbilityVisualEditorDocument d){for(var t:SkillVfxModel.PrimitiveType.values()){var primitive=SkillVfxModel.defaults("x"+t,t);var fields=SkillEditorUiController.inspectorFields(primitive);assert fields.contains("delayTicks")&&fields.contains("argb")&&fields.containsAll(AbilityVisualPropertySchemas.all().get(t));}assert ((SkillVfxModel.Literal)SkillVfxModel.defaults("burst",SkillVfxModel.PrimitiveType.BURST).value("count")).value()==8;d.select("primitive","cast-point");var width=AbilityVisualPropertySchemas.schema(SkillVfxModel.PrimitiveType.POINT).property("width");@SuppressWarnings({"rawtypes","unchecked"}) io.github.gyai.projects.editor.core.PropertyDescriptor raw=width;raw.write(d,.25d);assert d.dirty()&&((Double)d.selectedValue("width"))==.25d&&d.undo();var radius=new SkillVfxModel.FromGameplay(SkillVfxModel.ActionField.RADIUS);assert SkillEditorUiController.mode(radius)==SkillEditorUiController.ScalarMode.FROM_GAMEPLAY;assert SkillEditorUiController.scalar(SkillEditorUiController.ScalarMode.FROM_GAMEPLAY,4,SkillVfxModel.ActionField.RADIUS).equals(radius);assert !SkillEditorUiController.number("bad").valid()&&!SkillEditorUiController.integer("300",1,256).valid()&&!SkillEditorUiController.argb("#123").valid();assert SkillEditorUiController.argb("#80112233").value()==0x80112233;}
 private static void duplicateSafety(SkillVfxModel.Snapshot snapshot){var d=new AbilityVisualEditorDocument(snapshot);d.execute(AbilityVisualCommands.duplicateEmission(SkillVfxModel.Hook.CAST,"cast"));var emissions=d.visual().emissions(SkillVfxModel.Hook.CAST);assert emissions.size()==2;var source=emissions.getFirst();var copy=emissions.get(1);assert source.actionIndex()==copy.actionIndex()&&source.primitives().size()==copy.primitives().size();var sourcePrimitive=source.primitives().getFirst();var copyPrimitive=copy.primitives().getFirst();assert !sourcePrimitive.id().equals(copyPrimitive.id());d.execute(AbilityVisualCommands.setScalar(copyPrimitive.id(),"size",new SkillVfxModel.Literal(7)));assert ((SkillVfxModel.Literal)sourcePrimitive.value("size")).value()==1;d.execute(AbilityVisualCommands.remove(copyPrimitive.id()));assert d.visual().emissions(SkillVfxModel.Hook.CAST).getFirst().primitives().size()==1;}
 private static void burstCount(){var burst=SkillVfxModel.defaults("burst",SkillVfxModel.PrimitiveType.BURST);var visual=new SkillVfxModel.Visual("projects:vfx/burst",List.of(new SkillVfxModel.HookBinding(SkillVfxModel.Hook.CAST,List.of(new SkillVfxModel.Emission("cast",-1,List.of(burst))))));var d=new AbilityVisualEditorDocument(new SkillVfxModel.Snapshot(UUID.randomUUID(),1,"projects:burst","Burst",visual.id(),"base","effective",false,List.of(),visual));d.select("primitive","burst");var count=AbilityVisualPropertySchemas.schema(SkillVfxModel.PrimitiveType.BURST).property("count");@SuppressWarnings({"rawtypes","unchecked"}) io.github.gyai.projects.editor.core.PropertyDescriptor raw=count;raw.write(d,new SkillVfxModel.Literal(2.7));assert d.selectedValue("count") instanceof SkillVfxModel.Literal literal&&literal.value()==3;raw.write(d,new SkillVfxModel.FromGameplay(SkillVfxModel.ActionField.RADIUS));assert ((SkillVfxModel.Literal)d.selectedValue("count")).value()==3;raw.write(d,new SkillVfxModel.Literal(99));assert ((SkillVfxModel.Literal)d.selectedValue("count")).value()==64;assert d.undo()&&((SkillVfxModel.Literal)d.selectedValue("count")).value()==3;assert d.undo()&&((SkillVfxModel.Literal)d.selectedValue("count")).value()==8;assert SkillVfxEditorProtocol.decodeVisual(SkillVfxEditorProtocol.encodeVisual(d.visual())).emissions(SkillVfxModel.Hook.CAST).getFirst().primitives().getFirst().value("count") instanceof SkillVfxModel.Literal;}
 private static void lifecycle()throws Exception{SkillEditorClientState.reset();var id=UUID.randomUUID();var catalog=List.of(new SkillVfxEditorProtocol.CatalogItem("projects:test","Test",true,"projects:vfx/test",1,"base","effective",false));var first=wire(snapshot(),1);pending(SkillVfxEditorProtocol.Operation.CATALOG,1,new UUID(0,0));SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,1,id,catalog,first,true,"",null));assert SkillEditorClientState.catalog().equals(catalog);var dirty=SkillEditorClientState.document();dirty.execute(AbilityVisualCommands.setScalar("circle","radius",new SkillVfxModel.Literal(4)));pending(SkillVfxEditorProtocol.Operation.APPLY_VISUAL_SESSION,2);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.STALE,2,id,List.of(),null,true,"changed",null));assert dirty.dirty()&&SkillEditorClientState.refreshRequired()&&!SkillEditorClientState.apply()&&!SkillEditorClientState.revert();pending(SkillVfxEditorProtocol.Operation.FETCH,3);var refreshed=wire(snapshot(),2);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,3,id,List.of(),refreshed,true,"",null));assert !SkillEditorClientState.refreshRequired()&&!SkillEditorClientState.document().dirty()&&SkillEditorClientState.document().baseline().revision()==2&&SkillEditorClientState.catalog().equals(catalog);var before=SkillEditorClientState.state();pending(SkillVfxEditorProtocol.Operation.FETCH,77);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.MALFORMED,0,new UUID(0,0),List.of(),null,false,"bad",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.state()==before&&SkillEditorClientState.catalog().equals(catalog)&&SkillEditorClientState.feedback()==SkillEditorController.Feedback.MALFORMED;SkillEditorClientState.reset();assert SkillEditorClientState.catalog().isEmpty()&&!SkillEditorClientState.refreshRequired();}
 private static void staleConflictPreservesSelectedDraft()throws Exception{SkillEditorClientState.reset();var id=UUID.randomUUID();var second=snapshot();second=new SkillVfxModel.Snapshot(second.session(),1,"projects:second","Second",second.visualId(),"base","effective",false,second.gameplay(),second.visual());var catalog=List.of(new SkillVfxEditorProtocol.CatalogItem("projects:first","First",true,"projects:vfx/first",1,"base","effective",false),new SkillVfxEditorProtocol.CatalogItem("projects:second","Second",true,second.visualId(),1,"base","effective",false));pending(SkillVfxEditorProtocol.Operation.CATALOG,1,new UUID(0,0));SkillEditorClientState.receiveV2(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,1,id,catalog,wire(second,1),true,"",null));var authority=SkillEditorClientState.state();var draft=SkillEditorClientState.document();draft.execute(AbilityVisualCommands.setScalar("circle","radius",new SkillVfxModel.Literal(9)));pending(SkillVfxEditorProtocol.Operation.APPLY_VISUAL_SESSION,2,id);SkillEditorClientState.receiveV2(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.STALE,2,id,List.of(),null,false,"stale",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.feedback()==SkillEditorController.Feedback.STALE&&SkillEditorClientState.refreshRequired()&&SkillEditorClientState.state()==authority&&SkillEditorClientState.document()==draft&&draft.dirty()&&SkillEditorClientState.catalog().equals(catalog)&&SkillEditorClientState.selectedAbility().equals("projects:second")&&SkillEditorClientState.previewAllowed()&&refreshTarget().equals("projects:second");pending(SkillVfxEditorProtocol.Operation.FETCH,3,id);SkillEditorClientState.receiveV2(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,3,id,List.of(),wire(second,2),true,"",null));assert !SkillEditorClientState.refreshRequired()&&SkillEditorClientState.selectedAbility().equals("projects:second");draft=SkillEditorClientState.document();draft.execute(AbilityVisualCommands.setScalar("circle","radius",new SkillVfxModel.Literal(10)));authority=SkillEditorClientState.state();pending(SkillVfxEditorProtocol.Operation.REVERT_VISUAL_SESSION,4,id);SkillEditorClientState.receiveV2(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.CONFLICT,4,id,List.of(),null,false,"conflict",null));assert SkillEditorClientState.feedback()==SkillEditorController.Feedback.CONFLICT&&SkillEditorClientState.refreshRequired()&&SkillEditorClientState.state()==authority&&SkillEditorClientState.document()==draft&&draft.dirty()&&SkillEditorClientState.selectedAbility().equals("projects:second")&&refreshTarget().equals("projects:second");pending(SkillVfxEditorProtocol.Operation.FETCH,5,id);SkillEditorClientState.receiveV2(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,5,id,List.of(),wire(second,3),true,"",null));assert !SkillEditorClientState.refreshRequired()&&!SkillEditorClientState.document().dirty()&&SkillEditorClientState.selectedAbility().equals("projects:second");SkillEditorClientState.reset();}
 private static void sessionApplyDenied()throws Exception{SkillEditorClientState.reset();var id=UUID.randomUUID();var catalog=List.of(new SkillVfxEditorProtocol.CatalogItem("projects:test","Test",true,"projects:vfx/test",1,"base","effective",false));pending(SkillVfxEditorProtocol.Operation.CATALOG,1,new UUID(0,0));SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,1,id,catalog,wire(snapshot(),1),true,"",null));var authority=SkillEditorClientState.state();var draft=SkillEditorClientState.document();draft.execute(AbilityVisualCommands.setScalar("circle","radius",new SkillVfxModel.Literal(9)));pending(SkillVfxEditorProtocol.Operation.APPLY_VISUAL_SESSION,41);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.PERMISSION_DENIED,41,id,List.of(),null,false,"session changes denied",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.sessionApplyDenied()&&SkillEditorClientState.feedback()==SkillEditorController.Feedback.DENIED;assert SkillEditorClientState.state()==authority&&SkillEditorClientState.catalog().equals(catalog)&&SkillEditorClientState.document()==draft&&draft.dirty()&&SkillEditorClientState.selectedAbility().equals("projects:test")&&SkillEditorClientState.previewAllowed();var header=SkillEditorUiController.header(draft,false,true,SkillEditorClientState.permitted()&&!SkillEditorClientState.sessionApplyDenied(),true);assert header.refresh()&&!header.apply()&&!header.revert()&&!SkillEditorClientState.apply()&&!SkillEditorClientState.revert();SkillEditorClientState.reset();assert !SkillEditorClientState.sessionApplyDenied()&&SkillEditorClientState.catalog().isEmpty();}
 private static void strictResponseLifecycle()throws Exception{SkillEditorClientState.reset();var id=UUID.randomUUID();var wrong=UUID.randomUUID();var catalog=List.of(new SkillVfxEditorProtocol.CatalogItem("projects:test","Test",true,"projects:vfx/test",1,"base","effective",false));pending(SkillVfxEditorProtocol.Operation.CATALOG,1,new UUID(0,0));SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,1,id,catalog,wire(snapshot(),1),true,"",null));var authority=SkillEditorClientState.state();var document=SkillEditorClientState.document();var feedback=SkillEditorClientState.feedback();SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.PERMISSION_DENIED,99,wrong,List.of(),null,false,"unsolicited",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.state()==authority&&SkillEditorClientState.document()==document&&SkillEditorClientState.catalog().equals(catalog)&&SkillEditorClientState.feedback()==feedback&&!SkillEditorClientState.sessionApplyDenied();pending(SkillVfxEditorProtocol.Operation.FETCH,7);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,8,wrong,List.of(),wire(snapshot(),8),false,"mismatch",null));assert SkillEditorClientState.pending()&&SkillEditorClientState.state()==authority;SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.MALFORMED,0,wrong,List.of(),null,false,"terminal",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.feedback()==SkillEditorController.Feedback.MALFORMED&&SkillEditorClientState.state()==authority;SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,7,wrong,List.of(),wire(snapshot(),7),false,"late",null));assert SkillEditorClientState.state()==authority&&SkillEditorClientState.feedback()==SkillEditorController.Feedback.MALFORMED;document.execute(AbilityVisualCommands.setScalar("circle","radius",new SkillVfxModel.Literal(8)));pending(SkillVfxEditorProtocol.Operation.APPLY_VISUAL_SESSION,9,id);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.PERMISSION_DENIED,9,wrong,List.of(),null,false,"wrong session",null));assert SkillEditorClientState.pending()&&!SkillEditorClientState.sessionApplyDenied()&&SkillEditorClientState.state()==authority;SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.PERMISSION_DENIED,9,id,List.of(),null,false,"denied",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.sessionApplyDenied()&&SkillEditorClientState.state()==authority;SkillEditorClientState.reset();pending(SkillVfxEditorProtocol.Operation.CATALOG,1,new UUID(0,0));SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.OK,1,id,catalog,wire(snapshot(),1),true,"",null));pending(SkillVfxEditorProtocol.Operation.REVERT_VISUAL_SESSION,12,id);SkillEditorClientState.receive(new SkillVfxEditorProtocol.State(SkillVfxEditorProtocol.Status.PERMISSION_DENIED,12,id,List.of(),null,false,"revert denied",null));assert !SkillEditorClientState.pending()&&SkillEditorClientState.sessionApplyDenied()&&SkillEditorClientState.feedback()==SkillEditorController.Feedback.DENIED;SkillEditorClientState.reset();assert !SkillEditorClientState.sessionApplyDenied();}
 private static SkillVfxEditorProtocol.Snapshot wire(SkillVfxModel.Snapshot value,long revision){return new SkillVfxEditorProtocol.Snapshot(value.abilityId(),value.abilityName(),value.gameplay(),value.visualId(),value.visual(),value.visual(),revision,"base"+revision,"effective"+revision,false);}
 private static void pending(SkillVfxEditorProtocol.Operation operation,long correlation)throws Exception{var type=SkillEditorClientState.class;var session=type.getDeclaredField("session");session.setAccessible(true);UUID request=(UUID)session.get(null);pending(operation,correlation,request==null?new UUID(0,0):request);}
