 private static void timeline(SkillVfxModel.Visual v){var p=new SkillVfxPreviewController();var t=p.timeline();t.play();t.advance(2,20);assert t.playing()&&t.ticks()==2;t.pause();assert !t.playing();t.restart();p.loop();t.seek(19);t.advance(2,20);assert t.playing()&&t.ticks()==1;p.cycleSpeed();assert t.speed()==SkillVfxTimeline.Speed.DOUBLE;t.stop();var player=new SkillVfxPreviewController.Vec(1,4,2);var look=new SkillVfxPreviewController.Vec(0,0,2);assert p.origin(player,look).equals(player);p.cycleAnchor();assert p.origin(player,look).equals(new SkillVfxPreviewController.Vec(1,4,5));assert t.bars(v,SkillVfxModel.Hook.TELEGRAPH).size()==1;var viewport=new SkillVfxTimelinePresentation.Rect(6,30,628,48);var view=SkillVfxTimelinePresentation.layout(List.of(new SkillVfxTimeline.Bar("one",2,12),new SkillVfxTimeline.Bar("two",12,20)),20,8,viewport);assert view.startTick()==0&&view.endTick()==20&&view.bars().size()==2&&view.bars().get(0).bounds().x()>=6&&view.bars().get(1).bounds().x()+view.bars().get(1).bounds().width()<=634;assert SkillVfxTimelinePresentation.seekTick(6,20,viewport)==0&&SkillVfxTimelinePresentation.seekTick(634,20,viewport)==20&&SkillVfxTimelinePresentation.seekTick(-10,20,viewport)==0;}
 private static void layout(){var l=new SkillEditorLayout();var n=l.bounds(640,360);assert n.tree().width()>=80&&n.inspector().width()>=100&&n.timeline().height()>=40&&l.inspectorPageSize(n.inspector())==2&&l.treeNodeRows(n.tree())>=2&&l.treeActionRows(n.tree())>=5&&l.bezierControlPage(n.inspector());assert n.tree().y()+n.tree().height()<=360&&n.inspector().y()+n.inspector().height()<=360&&n.preview().x()+n.preview().width()<=640;java.util.function.ToIntFunction<String> wide=text->{int measured=0;for(int at=0;at<text.length();){int point=text.codePointAt(at);measured+=point>=0x3000?9:6;at+=Character.charCount(point);}return measured;};var previewHelp=l.previewHelp(n.preview(),wide);String previewText=String.join("",previewHelp.lines().stream().map(SkillEditorLayout.PreviewHelpLine::text).toList());assert previewHelp.fits(n.preview(),wide)&&previewHelp.controlsY()==128&&previewHelp.controlsBounds().within(n.preview())&&previewText.contains("プレイヤー周囲のワールド内に")&&previewText.contains("カメラを動かして見え方を確認してください。");var normal=l.previewStatus(n.preview(),"発動時","点","プレイヤー周囲",true,"",wide);assert normal.fits(n.preview(),wide)&&normal.lines().get(0).text().equals("現在: 発動時 > 点")&&normal.lines().get(1).text().equals("表示: プレイヤー周囲")&&normal.lines().get(2).text().equals("状態: プレビュー可能")&&previewHelp.controlsBounds().y()+previewHelp.controlsBounds().height()<=normal.lines().getFirst().bounds().y();var denied=l.previewStatus(n.preview(),"発動時","ベジェ曲線","プレイヤー前方3m",false,"接続待ち",wide);assert denied.fits(n.preview(),wide)&&denied.lines().get(0).text().contains("ベジェ曲線")&&denied.lines().get(1).text().contains("プレイヤー前方3m")&&denied.lines().get(2).text().contains("権限なし")&&denied.lines().get(2).text().contains("接続待ち");var longError=l.previewStatus(n.preview(),"発動時","ベジェ曲線","プレイヤー周囲",true,"ローカル🪄プレビューを開始できません。".repeat(8),wide);assert longError.fits(n.preview(),wide)&&longError.lines().get(2).text().contains("エラー")&&longError.lines().get(2).text().endsWith("…")&&!Character.isHighSurrogate(longError.lines().get(2).text().charAt(longError.lines().get(2).text().length()-2));var header=l.inspectorHeader(n.inspector());assert header.nonOverlapping()&&header.title().within(n.inspector())&&header.page().within(n.inspector())&&header.previous().within(n.inspector())&&header.next().within(n.inspector())&&header.content().within(n.inspector());var field=l.inspectorField(n.inspector(),0);assert field.ordered()&&field.label().within(header.content())&&field.input().within(header.content())&&field.help().within(header.content());int bezierLastCoordinateY=field.help().y()+field.help().height()+1+3*18;assert bezierLastCoordinateY+18<=n.inspector().y()+n.inspector().height()-6;var narrow=new SkillEditorLayout.Rect(400,52,240,188);assert l.inspectorTitle(SkillVfxModel.PrimitiveType.BEZIER,0,1,14,narrow).equals("詳細: ベジェ曲線")&&l.inspectorTitleWidth(narrow)==228&&l.inspectorPageLabel(0,1,14).equals("1〜1 / 14");assert l.inspectorTitle(SkillVfxModel.PrimitiveType.BEZIER,0,1,14,new SkillEditorLayout.Rect(0,0,300,188)).contains("BEZIER");assert l.primaryActions(640).size()==6&&l.primaryActions(640).stream().allMatch(r->r.x()>=0&&r.y()>=0&&r.x()+r.width()<=640&&r.y()+r.height()<=360);for(var type:SkillVfxModel.PrimitiveType.values())assert (AbilityVisualPropertySchemas.fields(type).size()+l.inspectorPageSize(n.inspector())-1)/l.inspectorPageSize(n.inspector())>=1;l.dragLeft(999,640);l.dragRight(0,640);l.dragBottom(0,360);assert l.bounds(1,1).preview().width()>=0;l.visibleTree(false);l.visiblePreview(false);l.visibleInspector(false);l.visibleTimeline(false);assert l.bounds(1,1).timeline().height()==0;l.reset();assert l.bounds(640,360).tree().width()>0;}
 private static void japaneseInspectorLayout(){var layout=new SkillEditorLayout();java.util.function.ToIntFunction<String> font=text->{int width=0;for(int i=0;i<text.length();){int cp=text.codePointAt(i);width+=cp>=0x3000?10:6;i+=Character.charCount(cp);}return width;};var props=List.of(new SkillEditorLayout.InspectorProperty("a","開始まで","このパーツを表示し始めるまでのティック数です。長い日本語説明も折り返します。",18),new SkillEditorLayout.InspectorProperty("line","制御点","線の座標です。",80),new SkillEditorLayout.InspectorProperty("bezier","ベジェ制御点","ベジェ曲線の座標です。",80),new SkillEditorLayout.InspectorProperty("b","描画角度","描画する角度の範囲です。",18));for(var rect:List.of(layout.bounds(640,360).inspector(),layout.bounds(1920,1080).inspector())){int pages=layout.inspectorPage(rect,props,0,font,9).pages();for(int pageIndex=0;pageIndex<pages;pageIndex++){var page=layout.inspectorPage(rect,props,pageIndex,font,9);assert page.reachable();var content=layout.inspectorHeader(rect).content();for(var entry:page.entries())assert entry.field().ordered()&&entry.field().label().within(content)&&entry.field().input().within(content)&&entry.field().feedback().within(content)&&entry.field().help().within(content);for(int i=1;i<page.entries().size();i++)assert page.entries().get(i-1).field().help().y()+page.entries().get(i-1).field().help().height()<=page.entries().get(i).field().label().y();for(var entry:page.entries())if(entry.property().id().equals("line")||entry.property().id().equals("bezier"))assert entry.field().input().y()+20+2*30<=entry.field().input().y()+entry.field().input().height();}}var compact=layout.previewPage(layout.bounds(640,360).preview(),false,"発動時","ベジェ曲線","プレイヤー周囲",true,"",font);var detail=layout.previewPage(layout.bounds(640,360).preview(),true,"発動時","ベジェ曲線","プレイヤー周囲",true,"",font);assert compact.fits(layout.bounds(640,360).preview(),font)&&detail.fits(layout.bounds(640,360).preview(),font)&&compact.world().within(layout.bounds(640,360).preview())&&detail.play().within(layout.bounds(640,360).preview())&&detail.anchor().within(layout.bounds(640,360).preview());}
